<div class="admin-head"><div><span class="eyebrow">CENTRO DE CONTROL</span><h2 class="section">Dashboard administrativo</h2><p>Resumen de ventas, pedidos e inventario.</p></div><a class="btn grad" href="/?r=productForm">+ Nuevo producto</a></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="metric"><span>Ventas pagadas</span><b>Q<?=number_format($stats['sales'],2)?></b></div></div><div class="col-md-3"><div class="metric"><span>Pedidos</span><b><?=$stats['orders_count']?></b></div></div><div class="col-md-3"><div class="metric"><span>Ticket promedio</span><b>Q<?=number_format($stats['avg_sale'],2)?></b></div></div><div class="col-md-3"><div class="metric"><span>Entregados</span><b><?=$stats['delivered']?></b></div></div></div><div class="row g-4"><div class="col-lg-6"><div class="card p-4"><h4>Pedidos por estado</h4><?php foreach($states as $s):?><div class="reportbar"><span><?=e($s['status'])?></span><b><?=$s['qty']?></b></div><?php endforeach;?></div></div><div class="col-lg-6"><div class="card p-4"><h4>Alertas de inventario</h4><?php if(!$low):?><p class="text-success">No hay productos con stock bajo.</p><?php endif;?><?php foreach($low as $p):?><div class="reportbar"><span><?=e($p['name'])?></span><b class="text-danger"><?=$p['stock']?> / mínimo <?=$p['min_stock']?></b></div><?php endforeach;?></div></div></div>